// e15 (2026-10-23) dq_arena: GENERATED by tools/build_dq_arena.py from eval48 dq_ref.cu (addressing only).
// eval48 (2026-10-22): fp32 reference-semantics HTR-W1 decode to the original basis, batched over experts.
// W[b] = (H . (cb[s] * scale_row) . H) * sv_row * su_col -> bf16, per 128x128 block, exactly the op sequence of the sealed
// htr/wire.py dequant (codebook gather from the same fp32 table, fp32 scale multiply, transform along rows, then along
// columns, signs, RNE bf16) except that each 128-point Hadamard is a fp32 butterfly followed by * 1/sqrt(128) instead of a
// GEMM against the normalized matrix (summation order differs -> last-bit fp32 differences, rare 1-ulp bf16 flips).
// Unlike e10 k_dequant_w there is NO f16 intermediate: the 128x128 block is kept in fp32 LDS (64 KiB, XOR-swizzled).
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>
#include <stdint.h>

template <int MSK> __device__ __forceinline__ float shx(float v) {
  const int iv = __builtin_bit_cast(int, v);
  if constexpr (MSK < 16) {
    return __builtin_bit_cast(float, __builtin_amdgcn_update_dpp(0, iv, 0x160 | MSK, 0xF, 0xF, false));
  } else {
    return __builtin_bit_cast(float, (int)__builtin_amdgcn_permlanex16((unsigned)iv, (unsigned)iv, 0x76543210u, 0xfedcba98u, false, false));
  }
}
template <int MSK> __device__ __forceinline__ void fwht_stage(float v[4], int lane) {
  const bool up = (lane & MSK) != 0;
#pragma unroll
  for (int e = 0; e < 4; ++e) {
    const float o = shx<MSK>(v[e]);
    v[e] = up ? (o - v[e]) : (v[e] + o);
  }
}
__device__ __forceinline__ void fwht128_wave(float v[4], int lane) {
  float a = v[0] + v[1], b = v[0] - v[1], c = v[2] + v[3], d = v[2] - v[3];
  v[0] = a + c; v[1] = b + d; v[2] = a - c; v[3] = b - d;
  fwht_stage<1>(v, lane); fwht_stage<2>(v, lane); fwht_stage<4>(v, lane); fwht_stage<8>(v, lane); fwht_stage<16>(v, lane);
}

#define SWZ(r, c) ((r) * 128 + ((c) ^ (((r) >> 2) & 31)))

template <int K>
__global__ __launch_bounds__(256) void k_dq_arena(const uint32_t* __restrict__ qw, const __half* __restrict__ scales,
                                                const float* __restrict__ cbtab, const uint8_t* __restrict__ su,
                                                const uint8_t* __restrict__ sv, __nv_bfloat16* __restrict__ W, int mt, int nt,
                                                const int64_t* __restrict__ qoff, int role, int pad, int s_off, int s_es,
                                                int su_off, int su_es, int sv_off, int sv_es, int64_t w_es) {
  __shared__ float L[128 * 128];
  constexpr int NW = 8 * K, NB = 256 * K;
  const int bx = blockIdx.x, by = blockIdx.y, t = threadIdx.x, lane = t & 31, w = t >> 5;
  const size_t b = blockIdx.z;
  const int m = mt * 16, n = nt * 16;
  // e15: arena addressing (was: dense [B, mt, nt, NW] / [B, m] / [B, n/8] / [B, m/8] / [B, m, n])
  qw += qoff[b * 3 + role]; scales += b * (size_t)s_es + s_off; su += b * (size_t)su_es + su_off; sv += b * (size_t)sv_es + sv_off;
  W += b * (size_t)w_es;
  const size_t pitch = (size_t)nt * NW + pad;          // words per 16-row strip incl. the e12 per-K strip padding
  const float inv = 1.0f / 11.313708498984761f;
  for (int c = w; c < 128; c += 8) {                       // transform each column along its 128 rows
    const int tj = bx * 8 + (c >> 4), cc = c & 15;
    float v[4];
#pragma unroll
    for (int e = 0; e < 4; ++e) {
      const int r = lane * 4 + e, ti = by * 8 + (r >> 4), p = (r & 15) * 16 + cc;
      const uint32_t* tp = qw + (size_t)ti * pitch + (size_t)tj * NW;
      const int b0 = ((p + 1) * K - 16 + NB) % NB, wi = b0 >> 5, off = b0 & 31;
      const uint64_t comb = ((uint64_t)tp[wi] << 32) | (uint64_t)tp[(wi + 1) % NW];
      const uint32_t s = (uint32_t)(comb >> (48 - off)) & 0xFFFFu;
      v[e] = cbtab[s] * __half2float(scales[by * 128 + r]);
    }
    fwht128_wave(v, lane);
#pragma unroll
    for (int e = 0; e < 4; ++e) { const int r = lane * 4 + e; L[SWZ(r, c)] = v[e] * inv; }
  }
  __syncthreads();
  for (int r = w; r < 128; r += 8) {                       // transform each row along its 128 columns, signs, bf16
    float v[4];
#pragma unroll
    for (int e = 0; e < 4; ++e) v[e] = L[SWZ(r, lane * 4 + e)];
    fwht128_wave(v, lane);
    const int gr = by * 128 + r;
    const bool nr = (sv[gr >> 3] >> (gr & 7)) & 1;
    __nv_bfloat16 o[4];
#pragma unroll
    for (int e = 0; e < 4; ++e) {
      const int gc = bx * 128 + lane * 4 + e;
      float x = v[e] * inv;
      if (nr) x = -x;
      if ((su[gc >> 3] >> (gc & 7)) & 1) x = -x;
      o[e] = __float2bfloat16(x);
    }
    *reinterpret_cast<uint2*>(W + (size_t)gr * n + bx * 128 + lane * 4) = *reinterpret_cast<uint2*>(o);
  }
}

// role 0 gate / 1 up / 2 down of all E experts of one uniform-K arena -> out view [E, *, n] (expert stride w_es elements,
// rows start at row_off). m, n: role geometry (gate/up 640x2560, down 2560x640). Offsets/strides in elements.
void dq_arena(torch::Tensor qw, torch::Tensor qoff, torch::Tensor scales, torch::Tensor su, torch::Tensor sv, torch::Tensor cbtab,
              int64_t K, int64_t role, int64_t pad, int64_t m, int64_t n, int64_t s_off, int64_t s_es, int64_t su_off, int64_t su_es,
              int64_t sv_off, int64_t sv_es, torch::Tensor out, int64_t w_es, int64_t row_off) {
  TORCH_CHECK(qw.is_cuda() && qw.is_contiguous() && qw.scalar_type() == torch::kInt32, "qw int32 arena words");
  TORCH_CHECK(qoff.is_contiguous() && qoff.scalar_type() == torch::kInt64 && qoff.dim() == 2 && qoff.size(1) == 3, "qoff [E, 3] int64");
  const int E = qoff.size(0);
  TORCH_CHECK(m % 128 == 0 && n % 128 == 0 && role >= 0 && role <= 2 && pad >= 0, "geometry");
  TORCH_CHECK(scales.is_contiguous() && scales.scalar_type() == torch::kHalf && scales.numel() == (int64_t)E * s_es && s_off + m <= s_es);
  TORCH_CHECK(su.is_contiguous() && su.scalar_type() == torch::kUInt8 && su.numel() == (int64_t)E * su_es && su_off + n / 8 <= su_es);
  TORCH_CHECK(sv.is_contiguous() && sv.scalar_type() == torch::kUInt8 && sv.numel() == (int64_t)E * sv_es && sv_off + m / 8 <= sv_es);
  TORCH_CHECK(cbtab.is_contiguous() && cbtab.scalar_type() == torch::kFloat && cbtab.numel() == 65536);
  TORCH_CHECK(out.is_cuda() && out.is_contiguous() && out.scalar_type() == torch::kBFloat16 && out.dim() == 3 && out.size(0) == E &&
              out.size(2) == n && out.stride(0) == w_es && row_off + m <= out.size(1), "out [E, rows, n] bf16");
  auto st = at::cuda::getCurrentCUDAStream();
  const int mt = m / 16, nt = n / 16;
  dim3 grid(nt / 8, mt / 8, E);
  const uint32_t* q = reinterpret_cast<const uint32_t*>(qw.data_ptr<int32_t>());
  const __half* sc = reinterpret_cast<const __half*>(scales.data_ptr<at::Half>());
  __nv_bfloat16* o = reinterpret_cast<__nv_bfloat16*>(out.data_ptr<at::BFloat16>()) + (size_t)row_off * n;
  const float* cb = cbtab.data_ptr<float>();
  const int64_t* qo = qoff.data_ptr<int64_t>();
  if (K == 4) {
    k_dq_arena<4><<<grid, 256, 0, st>>>(q, sc, cb, su.data_ptr<uint8_t>(), sv.data_ptr<uint8_t>(), o, mt, nt, qo, (int)role, (int)pad,
                                       (int)s_off, (int)s_es, (int)su_off, (int)su_es, (int)sv_off, (int)sv_es, w_es);
  } else if (K == 3) {
    k_dq_arena<3><<<grid, 256, 0, st>>>(q, sc, cb, su.data_ptr<uint8_t>(), sv.data_ptr<uint8_t>(), o, mt, nt, qo, (int)role, (int)pad,
                                       (int)s_off, (int)s_es, (int)su_off, (int)su_es, (int)sv_off, (int)sv_es, w_es);
  } else if (K == 5) {
    k_dq_arena<5><<<grid, 256, 0, st>>>(q, sc, cb, su.data_ptr<uint8_t>(), sv.data_ptr<uint8_t>(), o, mt, nt, qo, (int)role, (int)pad,
                                       (int)s_off, (int)s_es, (int)su_off, (int)su_es, (int)sv_off, (int)sv_es, w_es);
  } else {
    TORCH_CHECK(false, "K must be 3, 4 or 5");
  }
}
